import{_ as a,o as t,c as s,ae as n}from"./chunks/framework.BNlBHJQh.js";const h=JSON.parse('{"title":"Query Parameters","description":"","frontmatter":{},"headers":[],"relativePath":"api/query-params.md","filePath":"api/query-params.md"}'),o={name:"api/query-params.md"};function i(r,e,d,p,l,c){return t(),s("div",null,[...e[0]||(e[0]=[n(`<h1 id="query-parameters" tabindex="-1">Query Parameters <a class="header-anchor" href="#query-parameters" aria-label="Permalink to &quot;Query Parameters&quot;">​</a></h1><p>Hiroki parses URL query parameters into a typed <code>HirokiQuery</code> AST before passing to the adapter. All adapters (Mongoose, Memory, custom) receive the same normalized query.</p><h2 id="filtering-where" tabindex="-1">Filtering (<code>where</code>) <a class="header-anchor" href="#filtering-where" aria-label="Permalink to &quot;Filtering (\`where\`)&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GET /api/users?where[name]=alice</span></span>
<span class="line"><span># → { field: &#39;name&#39;, op: &#39;eq&#39;, value: &#39;alice&#39; }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>GET /api/users?where[age][$gt]=18</span></span>
<span class="line"><span># → { field: &#39;age&#39;, op: &#39;gt&#39;, value: 18 }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>GET /api/users?where[role][$in]=admin,user</span></span>
<span class="line"><span># → { field: &#39;role&#39;, op: &#39;in&#39;, value: [&#39;admin&#39;, &#39;user&#39;] }</span></span></code></pre></div><h3 id="supported-operators" tabindex="-1">Supported operators <a class="header-anchor" href="#supported-operators" aria-label="Permalink to &quot;Supported operators&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Operator</th><th>Description</th></tr></thead><tbody><tr><td><em>(none)</em></td><td>equal (<code>eq</code>)</td></tr><tr><td><code>$eq</code></td><td>equal</td></tr><tr><td><code>$ne</code></td><td>not equal</td></tr><tr><td><code>$gt</code></td><td>greater than</td></tr><tr><td><code>$gte</code></td><td>greater than or equal</td></tr><tr><td><code>$lt</code></td><td>less than</td></tr><tr><td><code>$lte</code></td><td>less than or equal</td></tr><tr><td><code>$in</code></td><td>in array (comma-separated)</td></tr><tr><td><code>$nin</code></td><td>not in array (comma-separated)</td></tr><tr><td><code>$regex</code></td><td>regex match</td></tr></tbody></table><p>Multiple <code>where</code> filters are AND-combined.</p><h2 id="sorting" tabindex="-1">Sorting <a class="header-anchor" href="#sorting" aria-label="Permalink to &quot;Sorting&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GET /api/users?sort=name          # ascending by name</span></span>
<span class="line"><span>GET /api/users?sort=-name         # descending by name</span></span>
<span class="line"><span>GET /api/users?sort=-name,age     # desc name, then asc age</span></span></code></pre></div><h2 id="pagination" tabindex="-1">Pagination <a class="header-anchor" href="#pagination" aria-label="Permalink to &quot;Pagination&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GET /api/users?limit=10</span></span>
<span class="line"><span>GET /api/users?offset=20          # or: skip=20</span></span>
<span class="line"><span>GET /api/users?limit=10&amp;offset=20</span></span></code></pre></div><h2 id="field-selection" tabindex="-1">Field selection <a class="header-anchor" href="#field-selection" aria-label="Permalink to &quot;Field selection&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GET /api/users?select=name,email  # only name and email fields</span></span></code></pre></div><h2 id="count" tabindex="-1">Count <a class="header-anchor" href="#count" aria-label="Permalink to &quot;Count&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GET /api/users?count=true              # total count</span></span>
<span class="line"><span>GET /api/users?count=true&amp;where[active]=true   # filtered count</span></span></code></pre></div><p>Returns a number, not an array.</p><h2 id="distinct" tabindex="-1">Distinct <a class="header-anchor" href="#distinct" aria-label="Permalink to &quot;Distinct&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GET /api/users?distinct=role   # unique values of &#39;role&#39; field</span></span></code></pre></div><h2 id="populate-mongoose-only" tabindex="-1">Populate (Mongoose only) <a class="header-anchor" href="#populate-mongoose-only" aria-label="Permalink to &quot;Populate (Mongoose only)&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GET /api/users?populate=posts         # populate by field name</span></span>
<span class="line"><span>GET /api/users?populate={&quot;path&quot;:&quot;posts&quot;,&quot;select&quot;:&quot;title&quot;}</span></span></code></pre></div><h2 id="legacy-conditions" tabindex="-1">Legacy conditions <a class="header-anchor" href="#legacy-conditions" aria-label="Permalink to &quot;Legacy conditions&quot;">​</a></h2><p>The <code>conditions</code> parameter is kept for backward compatibility:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GET /api/users?conditions={&quot;name&quot;:&quot;alice&quot;}          # JSON string</span></span>
<span class="line"><span>GET /api/users?conditions[name]=alice               # bracket notation</span></span></code></pre></div><p>Prefer <code>where[]</code> for new code — it works across all adapters.</p><h2 id="value-coercion" tabindex="-1">Value coercion <a class="header-anchor" href="#value-coercion" aria-label="Permalink to &quot;Value coercion&quot;">​</a></h2><p>Hiroki automatically coerces query string values:</p><table tabindex="0"><thead><tr><th>String</th><th>Becomes</th></tr></thead><tbody><tr><td><code>&quot;true&quot;</code></td><td><code>true</code> (boolean)</td></tr><tr><td><code>&quot;false&quot;</code></td><td><code>false</code> (boolean)</td></tr><tr><td><code>&quot;42&quot;</code></td><td><code>42</code> (number)</td></tr><tr><td><code>&quot;alice&quot;</code></td><td><code>&quot;alice&quot;</code> (string)</td></tr></tbody></table>`,27)])])}const g=a(o,[["render",i]]);export{h as __pageData,g as default};
